import { Activity, AlertTriangle, ArrowLeft, ArrowRight, Ban, CircleDashed, ClipboardCheck, Copy, FileCheck2, FolderKanban, GitBranch, KeyRound, PackageCheck, RefreshCw, ShieldCheck, Sparkles, Users, Wrench } from 'lucide-react';
import { useState, type ReactNode } from 'react';
import { Link, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { post } from '../../api';
import { Button, Empty, Status } from '../../components/ui';
import { AdminEnvironmentPanel, AdminSOPPanel, CreateProductModal, createAdminProduct, emptyAdminProductDraft } from '../WorkOSConfigPanels';
import { useAdmin } from '../context';
import { adminCapabilityPath, adminCustomerPath, adminCustomersForProductPath, adminExecutorPath, adminPath, adminProductPath, adminProductVersionPath, adminReleaseResultPath, adminSkillPath } from '../routes';
import { auditActionLabel, auditSubjectLabel } from '../../uiLabels';

const dateTime = (value:string) => new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value));

export function AdminOperationsOverview() {
  const {workOS,executorDirectory,executorDirectoryError,refresh,refreshing}=useAdmin();
  const navigate=useNavigate();
  if (!workOS) return <OperationsEmpty title="运营数据暂不可用" detail="后台还没有返回运营总览数据。"/>;
  const published=workOS.sops.flatMap(item=>item.versions.filter(version=>version.status==='published'));
  const drafts=workOS.sops.flatMap(item=>item.versions.filter(version=>version.status==='draft'));
  const onlineExecutors=executorDirectory?.executors.filter(item=>item.presence_status==='online')||[];
  const attentionGates=workOS.gates.filter(item=>['required_check','internal_review','client_decision'].includes(item.mode));
  const audit=workOS.audit.slice(0,5);
  return <div className="operations-page">
    <PageIntro eyebrow="后台 / 运营总览" title="运营总览" description="先处理客户正在等待的事情，再检查内容流程是否正常。" action={<button className="icon-button operations-refresh" aria-label="刷新数据" title="刷新数据" disabled={refreshing} onClick={()=>refresh(true)}><RefreshCw className={refreshing?'is-spinning':''} size={16}/></button>} />
    <section className="operations-brief"><div className="operations-brief-lead"><span className="operations-live-dot"/><div><strong>后台已连接</strong><span>数据更新于：{dateTime(executorDirectory?.generated_at||workOS.generated_at)}。{executorDirectoryError?'内容流程和任务数据已加载，电脑连接状态暂时不可用。':'当前显示的是最新的真实数据。'}</span></div></div><div className="operations-brief-facts"><span><small>已连接电脑</small><b>{executorDirectoryError?'暂不可用':`${onlineExecutors.length}/${executorDirectory?.executors.length||0}`}</b></span><span><small>进行中的任务</small><b>{workOS.usage.running_count}</b></span><span><small>等你确认</small><b>{workOS.usage.waiting_gate_count}</b></span></div></section>
    <section className="operations-stat-grid" aria-label="运营状态摘要">
      <SummaryStat icon={FolderKanban} label="创作流程" value={String(workOS.sops.length)} detail={`${published.length} 个已发布 · ${drafts.length} 个草稿`} tone="production" onClick={()=>navigate(adminPath('products'))}/>
      <SummaryStat icon={AlertTriangle} label="等你处理" value={String(workOS.usage.waiting_gate_count)} detail={`${attentionGates.length} 个地方需要确认`} tone="warning" onClick={()=>navigate(adminPath('alerts'))}/>
      <SummaryStat icon={Activity} label="全部任务" value={String(workOS.usage.task_count)} detail={`${workOS.usage.running_count} 个正在处理`} tone="info" onClick={()=>navigate(adminPath('jobs'))}/>
      <SummaryStat icon={ShieldCheck} label="最近变更" value={String(workOS.audit.length)} detail="系统操作记录" tone="success" onClick={()=>navigate(adminPath('audit'))}/>
    </section>
    <div className="operations-grid operations-grid-main">
      <section className="operations-section"><SectionTitle kicker="我的待办" title="现在要处理什么" action={<Link to={adminPath('alerts')}>查看全部 <ArrowRight size={14}/></Link>}/><div className="operations-list">{workOS.usage.waiting_gate_count>0?<OperationRow icon={ClipboardCheck} tone="warning" title={`${workOS.usage.waiting_gate_count} 个任务等你确认`} detail="确认后，后面的创作步骤才能继续" action="去处理" href={adminPath('alerts')}/>:<Empty title="目前没有需要确认的事" detail="新的发布、异常和结果风险会显示在这里。"/>}{drafts.length>0&&<OperationRow icon={GitBranch} tone="production" title={`${drafts.length} 个流程版本等待发布`} detail="检查内容后再发布给客户使用" action="查看版本" href={adminPath('products')}/>}<OperationRow icon={ShieldCheck} tone="success" title="历史设置都能查到" detail={`${workOS.audit.length} 条系统操作记录`} action="查看记录" href={adminPath('audit')}/></div></section>
      <section className="operations-section"><SectionTitle kicker="创作流程" title="流程发布情况" action={<Link to={adminPath('products')}>管理流程 <ArrowRight size={14}/></Link>}/><div className="operations-list">{workOS.sops.length===0?<Empty title="还没有创作流程" detail="创建创作流程后会显示在这里。"/>:workOS.sops.slice(0,5).map(item=><Link className="operations-list-row" to={adminProductPath(item.definition.id)} key={item.definition.id}><span className="operations-object-icon production"><FolderKanban size={16}/></span><span><strong>{item.definition.name}</strong><small>{item.versions.length} 个版本 · 当前 v{item.definition.current_version}</small></span><span className="operations-row-status">{item.versions.some(version=>version.status==='published')?'已发布':'待完善'}</span><ArrowRight size={14}/></Link>)}</div></section>
    </div>
    <div className="operations-grid">
      <section className="operations-section"><SectionTitle kicker="任务跟进" title="任务和电脑状态" action={<Link to={adminPath('jobs')}>查看任务进度 <ArrowRight size={14}/></Link>}/><div className="operations-health-list"><HealthLine label="进行中的任务" value={workOS.usage.running_count} tone="info"/><HealthLine label="等客户确认" value={workOS.usage.waiting_gate_count} tone="warning"/><HealthLine label="已准备好的功能" value={workOS.capabilities.length} tone="success"/><HealthLine label="已连接电脑" value={executorDirectoryError?'暂不可用':onlineExecutors.length} tone="production"/></div></section>
      <section className="operations-section"><SectionTitle kicker="最近变更" title="最近发生了什么" action={<Link to={adminPath('audit')}>查看全部 <ArrowRight size={14}/></Link>}/><div className="operations-list">{audit.length===0?<Empty title="还没有变更记录" detail="发布、保存和任务操作会出现在这里。"/>:audit.map(item=><div className="operations-audit-row" key={item.id}><ShieldCheck size={15}/><span><strong>{auditActionLabel(item.action)}</strong><small>{auditSubjectLabel(item.subject_type)} · {item.subject_id.slice(0, 12)}</small></span><time>{dateTime(item.created_at)}</time></div>)}</div></section>
    </div>
  </div>;
}

export function AdminProductsPage() {
  const {workOS,refresh}=useAdmin();
  const navigate=useNavigate();
  const [createOpen,setCreateOpen]=useState(false);
  const [createForm,setCreateForm]=useState(emptyAdminProductDraft);
  const [creating,setCreating]=useState(false);
  const [createNotice,setCreateNotice]=useState('');
  if (!workOS) return <OperationsEmpty title="创作流程暂不可用" detail="暂时无法读取创作流程，请稍后刷新。"/>;
  const createProduct=async()=>{setCreating(true);setCreateNotice('');try{const created=await createAdminProduct(createForm);await refresh(true);setCreateOpen(false);setCreateForm(emptyAdminProductDraft());navigate(adminProductPath(created.definition.id));}catch(value){setCreateNotice(value instanceof Error?value.message:'创作流程创建失败');}finally{setCreating(false);}};
  return <div className="operations-page"><PageIntro eyebrow="内容管理 / 创作流程" title="创作流程" description="管理客户实际使用的内容制作步骤和发布版本。" action={<><Button variant="secondary" onClick={()=>navigate(adminPath('releases'))}><GitBranch size={15}/>查看发布版本</Button><Button onClick={()=>setCreateOpen(true)}><FolderKanban size={15}/>新建创作流程</Button></>}/><section className="operations-section"><SectionTitle kicker="已登记流程" title={`${workOS.sops.length} 套创作流程`} action={<span className="operations-muted">进入流程后维护草稿和发布版本</span>}/><div className="operations-table"><header><span>创作流程</span><span>当前版本</span><span>发布状态</span><span>流程步骤</span><span>最近更新</span><span/></header>{workOS.sops.length===0?<Empty title="还没有创作流程" detail="创建创作流程后会显示在这里，页面不会生成演示数据。" action={<Button onClick={()=>setCreateOpen(true)}><FolderKanban size={15}/>新建创作流程</Button>}/>:workOS.sops.map(item=>{const current=item.versions.find(version=>version.version===item.definition.current_version)||item.versions[0];return <button className="operations-table-row" key={item.definition.id} onClick={()=>navigate(adminProductPath(item.definition.id))}><span className="operations-primary-cell"><span className="operations-object-icon production"><FolderKanban size={16}/></span><span><strong>{item.definition.name}</strong><small>{item.definition.description||'尚未填写流程说明'}</small></span></span><span>{current?`v${current.version}`:'尚未发布'}</span><span><Status value={current?.status||'draft'}/></span><span>{current?.stages.length||0} 步</span><span>{current?.created_at?dateTime(current.created_at):'暂无记录'}</span><ArrowRight size={15}/></button>})}</div></section>{createOpen&&<CreateProductModal form={createForm} setForm={setCreateForm} busy={creating} notice={createNotice} onClose={()=>{setCreateOpen(false);setCreateNotice('');}} onCreate={createProduct}/>}</div>;
}

export function AdminProductDetailPage() {
  const {productID='',version:versionValue}=useParams();
  const {workOS,refresh}=useAdmin();
  const navigate=useNavigate();
  if(!workOS)return <OperationsEmpty title="创作流程暂不可用" detail="暂时无法读取流程详情，请稍后刷新。"/>;
  const product=workOS.sops.find(item=>item.definition.id===productID);
  if(!product)return <OperationsNotFound title="没有找到这个创作流程" detail="它可能尚未登记，或者当前账号无权查看。"/>;
  const current=product.versions.find(item=>item.version===product.definition.current_version);
  const draft=product.versions.find(item=>item.status==='draft');
  const requestedVersion=versionValue?Number(versionValue):0;
  if(versionValue&&(!Number.isInteger(requestedVersion)||!product.versions.some(item=>item.version===requestedVersion)))return <OperationsNotFound title="没有找到这个产品版本" detail="请从产品详情选择仍然保留的版本。" href={adminProductPath(product.definition.id)}/>;
  const selectedVersion=requestedVersion||draft?.version||current?.version||product.versions[0]?.version||0;
  const selected=product.versions.find(item=>item.version===selectedVersion);
  const requiredCapabilities=new Set(selected?.stages.flatMap(stage=>stage.required_capabilities)||[]);
  const registeredCapabilities=new Set(workOS.capabilities.map(item=>item.id));
  const coveredCapabilities=Array.from(requiredCapabilities).filter(item=>registeredCapabilities.has(item)).length;
  const customerCount=workOS.environments.filter(item=>item.default_sop_id===product.definition.id).length;
  return <div className="operations-page operations-product-page">
    <Link className="operations-back-link" to={adminPath('products')}><ArrowLeft size={15}/>返回创作流程</Link>
    <PageIntro eyebrow="内容管理 / 创作流程" title={product.definition.name} description={product.definition.description||'尚未填写流程说明。'} action={<Link className="button button-secondary" to={adminCustomersForProductPath(product.definition.id)}><Users size={15}/>查看客户设置</Link>}/>
    <section className="operations-product-summary" aria-label="产品状态摘要">
      <div className="operations-product-summary-lead"><span className="operations-object-icon production"><FolderKanban size={18}/></span><span><small>当前维护版本</small><strong>{selected?`v${selected.version}`:'尚未创建版本'}</strong></span>{selected&&<Status value={selected.status}/>}</div>
      <div className="operations-product-facts"><span><small>当前发布</small><strong>{current?`v${current.version}`:'尚未发布'}</strong></span><span><small>编辑中</small><strong>{draft?`v${draft.version}`:'没有草稿'}</strong></span><span><small>开通客户</small><strong>{customerCount}</strong></span><span><small>功能准备情况</small><strong>{requiredCapabilities.size===0?'产品未说明':`${coveredCapabilities}/${requiredCapabilities.size}`}</strong></span></div>
    </section>
    <AdminSOPPanel key={product.definition.id} sops={[product]} environments={workOS.environments} initialSOPID={product.definition.id} initialVersion={selectedVersion} scoped onChanged={()=>refresh(true)} onPublished={(id,version)=>navigate(adminReleaseResultPath(id,version))} onSelectionChange={(id,version)=>navigate(adminProductVersionPath(id,version))}/>
  </div>;
}

export function AdminProductReleasesPage() {
  const {workOS}=useAdmin();
  if (!workOS) return <OperationsEmpty title="发布版本暂不可用" detail="暂时无法读取发布版本，请稍后刷新。"/>;
  const versions=workOS.sops.flatMap(item=>item.versions.map(version=>({version,product:item.definition.name,productID:item.definition.id})));
  return <div className="operations-page"><PageIntro eyebrow="内容管理 / 发布版本" title="发布版本" description="查看创作流程的版本、发布状态和历史设置。"/><section className="operations-section"><SectionTitle kicker="版本记录" title={`${versions.length} 个版本`} action={<span className="operations-muted">选择版本查看设置和影响</span>}/><div className="operations-table"><header><span>创作流程</span><span>版本</span><span>状态</span><span>流程步骤</span><span>发布时间</span><span/></header>{versions.length===0?<Empty title="还没有版本记录" detail="版本发布后会显示在这里。"/>:versions.sort((a,b)=>new Date(b.version.published_at||b.version.created_at).getTime()-new Date(a.version.published_at||a.version.created_at).getTime()).map(item=><Link className="operations-table-row" to={item.version.status==='published'?adminReleaseResultPath(item.productID,item.version.version):adminProductVersionPath(item.productID,item.version.version)} key={`${item.version.sop_id}:${item.version.version}`}><span className="operations-primary-cell"><span className="operations-object-icon strategy"><GitBranch size={16}/></span><span><strong>{item.product}</strong><small>{item.version.description||'暂无说明'}</small></span></span><span>v{item.version.version}</span><span><Status value={item.version.status}/></span><span>{item.version.stages.length} 步</span><span>{item.version.published_at?dateTime(item.version.published_at):'未发布'}</span><ArrowRight size={15}/></Link>)}</div></section></div>;
}

export function AdminReleaseResultPage() {
  const {productID='',version:versionValue=''}=useParams();
  const {workOS}=useAdmin();
  if(!workOS)return <OperationsEmpty title="发布结果暂不可用" detail="暂时无法读取发布版本，请稍后刷新。"/>;
  const product=workOS.sops.find(item=>item.definition.id===productID);
  const versionNumber=Number(versionValue);
  const version=product?.versions.find(item=>item.version===versionNumber);
  if(!product||!Number.isInteger(versionNumber)||!version)return <OperationsNotFound eyebrow="内容管理 / 发布版本" title="没有找到这个发布结果" detail="请从发布版本选择仍然保留的流程版本。" href={adminPath('releases')} returnLabel="返回发布版本"/>;
  if(version.status!=='published')return <OperationsNotFound eyebrow="创作运营 / 发布结果" title="这个版本没有有效的发布结果" detail="草稿或已停用版本仍可在产品详情中查看，但不能作为已发布结果展示。" href={adminProductVersionPath(product.definition.id,version.version)} returnLabel="查看产品版本"/>;
  const requiredCapabilities=Array.from(new Set(version.stages.flatMap(stage=>stage.required_capabilities)));
  const registeredCapabilities=new Set(workOS.capabilities.map(item=>item.id));
  const coveredCapabilities=requiredCapabilities.filter(item=>registeredCapabilities.has(item));
  const customers=workOS.environments.filter(item=>item.default_sop_id===product.definition.id&&item.default_sop_version===version.version);
  return <div className="operations-page operations-release-page">
    <Link className="operations-back-link" to={adminPath('releases')}><ArrowLeft size={15}/>返回发布版本</Link>
    <PageIntro eyebrow="内容管理 / 发布版本" title={`${product.definition.name} v${version.version} 已发布`} description="这个版本已经固定；后续修改需要创建新版本。" action={<Link className="button button-secondary" to={adminProductVersionPath(product.definition.id,version.version)}><FolderKanban size={15}/>返回流程版本</Link>}/>
    <section className="operations-release-conclusion"><span className="operations-release-check"><ShieldCheck size={22}/></span><div><strong>发布完成</strong><span>{customers.length} 个客户已固定使用这个版本；进行中的任务会继续使用开始时的版本。</span></div><Status value={version.status}/></section>
    <section className="operations-release-facts" aria-label="发布信息"><span><small>发布时间</small><strong>{version.published_at?dateTime(version.published_at):'暂未返回'}</strong></span><span><small>发布人</small><strong>{version.published_by||'未记录'}</strong></span><span><small>客户步骤</small><strong>{version.stages.length} 步</strong></span><span><small>功能准备情况</small><strong>{requiredCapabilities.length===0?'未说明':`${coveredCapabilities.length}/${requiredCapabilities.length}`}</strong></span></section>
    <div className="operations-grid operations-release-grid"><section className="operations-section"><SectionTitle kicker="已发布版本" title="发布信息" action={<Status value={version.status}/>}/><dl className="operations-release-details"><div><dt>创作产品</dt><dd>{product.definition.name}</dd></div><div><dt>版本</dt><dd>v{version.version}</dd></div><div><dt>设置记录</dt><dd><code>{version.digest||'暂未返回记录'}</code></dd></div><div><dt>所需功能</dt><dd>{requiredCapabilities.length?requiredCapabilities.map(capabilityLabel).join('、'):'产品未说明'}</dd></div></dl>{coveredCapabilities.length!==requiredCapabilities.length&&<div className="operations-release-note is-warning"><AlertTriangle size={16}/><span>当前功能清单还缺少 {requiredCapabilities.length-coveredCapabilities.length} 项；这不会改变已发布版本，但可能影响新任务完成对应步骤。</span></div>}</section><section className="operations-section"><SectionTitle kicker="客户开通" title={`${customers.length} 个客户固定此版本`} action={<Link to={adminCustomersForProductPath(product.definition.id)}>管理开通 <ArrowRight size={14}/></Link>}/><div className="operations-list">{customers.length===0?<Empty title="还没有客户固定此版本" detail="发布产品不会自动改变客户开通；需要在客户开通页明确选择版本。"/>:customers.map(customer=><Link className="operations-list-row" to={adminCustomerPath(customer.id)} key={customer.id}><span className="operations-object-icon success"><Users size={16}/></span><span><strong>{customer.name}</strong><small>{customer.status==='active'?'已启用新任务':'已暂停新任务'} · {customer.capabilities.filter(capability=>capability.enabled).length} 项功能</small></span><span className="operations-row-status">v{version.version}</span><ArrowRight size={14}/></Link>)}</div></section></div>
  </div>;
}

export function AdminCapabilityCatalogPage() {
  const {workOS}=useAdmin();
  if(!workOS)return <OperationsEmpty title="功能清单暂不可用" detail="暂时无法读取功能清单，请稍后刷新。"/>;
  return <div className="operations-page"><PageIntro eyebrow="功能设置 / 功能清单" title="功能清单" description="查看可用于创作流程的功能，以及哪些客户正在使用。"/><section className="operations-section"><SectionTitle kicker="已登记功能" title={`${workOS.capabilities.length} 项功能已登记`}/>{workOS.capabilities.length===0?<Empty title="还没有功能登记" detail="功能准备好后会显示在这里。"/>:<div className="operations-table operations-directory-table"><header><span>功能</span><span>版本</span><span>类型</span><span>使用位置</span><span>使用流程</span><span/></header>{workOS.capabilities.map(item=><Link className="operations-table-row" to={adminCapabilityPath(item.id,item.version)} key={`${item.id}:${item.version}`}><span className="operations-primary-cell"><span className="operations-object-icon info"><Sparkles size={16}/></span><span><strong>{capabilityLabel(item.id)}</strong><small>{capabilityDescription(item.id)}</small></span></span><span>{item.version}</span><span>{capabilityKindName(item.kind)}</span><span>{item.local_only?'连接的电脑':'平台或外部服务'}</span><span>{capabilityProductCount(workOS,item.id)} 个</span><ArrowRight size={15}/></Link>)}</div>}</section></div>;
}

export function AdminCapabilityDetailPage() {
  const {capabilityID='',capabilityVersion=''}=useParams();
  const {workOS}=useAdmin();
  if(!workOS)return <OperationsEmpty title="能力详情暂不可用" detail="暂时无法读取能力目录，请稍后刷新。"/>;
  const capability=workOS.capabilities.find(item=>item.id===capabilityID&&item.version===capabilityVersion);
  if(!capability)return <OperationsNotFound eyebrow="功能设置 / 功能清单" title="没有找到这个功能版本" detail="请从功能清单选择仍然可用的版本。" href={adminPath('capabilities')} returnLabel="返回功能清单"/>;
  const products=workOS.sops.flatMap(summary=>summary.versions.filter(version=>version.stages.some(stage=>stage.required_capabilities.includes(capability.id))).map(version=>({definition:summary.definition,version})));
  const productCount=new Set(products.map(item=>item.definition.id)).size;
  const environments=workOS.environments.filter(environment=>environment.capabilities.some(item=>item.id===capability.id&&item.version===capability.version&&item.enabled));
  return <div className="operations-page operations-capability-page"><Link className="operations-back-link" to={adminPath('capabilities')}><ArrowLeft size={15}/>返回功能清单</Link><PageIntro eyebrow="功能设置 / 功能清单" title={capabilityLabel(capability.id)} description={capabilityDescription(capability.id)}/><section className="operations-capability-banner"><span className="operations-object-icon info"><Sparkles size={18}/></span><div><strong>功能版本已登记</strong><span>这里只展示系统登记的信息，不代表自动处理已经批准，也不代表连接电脑当前可用。</span></div><span className="config-state is-info">仅供查看</span></section><section className="operations-release-facts" aria-label="功能摘要"><span><small>版本</small><strong>{capability.version}</strong></span><span><small>功能类型</small><strong>{capabilityKindName(capability.kind)}</strong></span><span><small>使用流程</small><strong>{productCount}</strong></span><span><small>已启用客户</small><strong>{environments.length}</strong></span></section><div className="operations-grid operations-capability-grid"><section className="operations-section"><SectionTitle kicker="功能详情" title="输入、输出和设置" action={<span className="operations-muted">{capability.local_only?'由工作电脑处理':'可由平台或外部服务处理'}</span>}/><dl className="operations-release-details"><div><dt>系统名称</dt><dd><code>{capability.id}</code></dd></div><div><dt>需要的输入</dt><dd><code>{capability.input_schema||'未登记'}</code></dd></div><div><dt>会生成的内容</dt><dd><code>{capability.output_schema||'未登记'}</code></dd></div><div><dt>展示方式</dt><dd>{capability.presentation_profiles?.length?capability.presentation_profiles.join('、'):'未登记'}</dd></div><div><dt>设置记录</dt><dd><code>{capability.digest||'未登记'}</code></dd></div></dl></section><section className="operations-section"><SectionTitle kicker="创作流程" title={`${products.length} 个版本使用此功能`} action={<Link to={adminPath('products')}>查看创作流程 <ArrowRight size={14}/></Link>}/><div className="operations-list">{products.length===0?<Empty title="还没有创作流程使用此功能" detail="创作流程添加这项功能后，会显示在这里。"/>:products.map(item=><Link className="operations-list-row" to={adminProductVersionPath(item.definition.id,item.version.version)} key={`${item.definition.id}:${item.version.version}`}><span className="operations-object-icon production"><FolderKanban size={16}/></span><span><strong>{item.definition.name}</strong><small>v{item.version.version} · 用于 {item.version.stages.filter(stage=>stage.required_capabilities.includes(capability.id)).length} 个创作步骤</small></span><Status value={item.version.status}/><ArrowRight size={14}/></Link>)}</div></section></div><section className="operations-section operations-capability-environments"><SectionTitle kicker="客户范围" title={`${environments.length} 个客户已启用此功能`} action={<Link to={adminPath('customers')}>查看客户设置 <ArrowRight size={14}/></Link>}/><div className="operations-list">{environments.length===0?<Empty title="还没有客户启用此功能版本" detail="客户可用功能会按版本显示在这里。"/>:environments.map(environment=><Link className="operations-list-row" to={adminCustomerPath(environment.id)} key={environment.id}><span className="operations-object-icon success"><Users size={16}/></span><span><strong>{environment.name}</strong><small>{environment.status==='active'?'可以开始新创作':'已暂停新创作'} · {productName(workOS,environment.default_sop_id,environment.default_sop_version)}</small></span><Status value={environment.status}/><ArrowRight size={14}/></Link>)}</div></section></div>;
}

export const AdminCustomersPage=()=> <AdminCustomerDirectory mode="enrollments"/>;
export const AdminTenantsPage=()=> <AdminCustomerDirectory mode="management"/>;

export function AdminSkillsPage() {
  const {skillDirectory,skillDirectoryError,refresh}=useAdmin();
  if(skillDirectoryError)return <OperationsEmpty title="自动化功能目录暂不可用" detail={skillDirectoryError} action={<Button variant="secondary" onClick={()=>refresh(true)}><RefreshCw size={15}/>重新加载</Button>}/>;
  if(!skillDirectory)return <OperationsEmpty title="自动化功能暂不可用" detail="暂时无法读取自动化功能目录，请稍后刷新。"/>;
  if(!skillDirectory.configured)return <div className="operations-page"><PageIntro eyebrow="功能设置 / 自动处理功能" title="自动处理功能" description="查看已经登记、检查并可用于新任务的自动处理功能。"/><section className="operations-section"><Empty title="自动处理功能目录还未配置" detail="系统还没有加载可用的自动处理功能，因此当前没有可使用的版本。"/></section></div>;
  return <div className="operations-page"><PageIntro eyebrow="功能设置 / 自动处理功能" title="自动处理功能" description="查看已登记的自动处理功能版本，以及它们能否用于新任务。"/><section className="operations-section"><SectionTitle kicker="已登记功能" title={`${skillDirectory.skills.length} 个自动处理功能版本`} action={<span className="operations-muted">目录版本 {skillDirectory.registry_schema_version||'未返回'}</span>}/>{skillDirectory.skills.length===0?<Empty title="还没有自动处理功能" detail="当前目录中还没有可用的自动处理功能。"/>:<div className="operations-table operations-skill-table"><header><span>自动处理功能</span><span>版本</span><span>当前状态</span><span>检查结果</span><span>新任务</span><span/></header>{skillDirectory.skills.map(skill=><Link className="operations-table-row" to={adminSkillPath(skill.id,skill.version)} key={`${skill.id}:${skill.version}`}><span className="operations-primary-cell"><span className={`operations-object-icon ${skill.available_for_new_runs?'success':'warning'}`}><PackageCheck size={16}/></span><span><strong>{skill.id}</strong><small>{skill.output_schemas.length} 种输出格式 · {skill.permissions.length} 项使用权限</small></span></span><span>{skill.version}</span><span><Status value={skill.lifecycle}/></span><span><Status value={skill.evaluation.status}/></span><span>{skill.available_for_new_runs?'可用于新任务':'暂不可用于新任务'}</span><ArrowRight size={15}/></Link>)}</div>}</section></div>;
}

export function AdminSkillDetailPage() {
  const {skillID='',skillVersion=''}=useParams();
  const {skillDirectory,skillDirectoryError,refresh}=useAdmin();
  if(skillDirectoryError)return <OperationsEmpty title="自动化功能详情暂不可用" detail={skillDirectoryError} action={<Button variant="secondary" onClick={()=>refresh(true)}><RefreshCw size={15}/>重新加载</Button>}/>;
  if(!skillDirectory)return <OperationsEmpty title="自动化功能详情暂不可用" detail="暂时无法读取自动化功能目录，请稍后刷新。"/>;
  const skill=skillDirectory.skills.find(item=>item.id===skillID&&item.version===skillVersion);
  if(!skill)return <OperationsNotFound eyebrow="功能设置 / 自动化功能" title="没有找到这个自动化功能版本" detail="请从自动化功能目录选择仍然保留的版本。" href={adminPath('skills')} returnLabel="返回自动化功能"/>;
  return <div className="operations-page operations-skill-page"><Link className="operations-back-link" to={adminPath('skills')}><ArrowLeft size={15}/>返回自动处理功能</Link><PageIntro eyebrow="功能设置 / 自动处理功能" title={skill.id} description="查看这项自动处理功能的来源、检查结果和使用范围。"/><section className="operations-capability-banner"><span className={`operations-object-icon ${skill.available_for_new_runs?'success':'warning'}`}><ShieldCheck size={18}/></span><div><strong>{skill.available_for_new_runs?'满足新任务使用条件':'暂不能用于新任务'}</strong><span>{skill.available_for_new_runs?'来源、检查、发布和停用状态均已通过核对。':'请先处理当前状态、检查结果或停用原因。'}</span></div><Status value={skill.lifecycle}/></section><section className="operations-release-facts" aria-label="自动处理功能摘要"><span><small>版本</small><strong>{skill.version}</strong></span><span><small>来源核验</small><strong>{skill.signature.status==='verified'?'已核验':'未核验'}</strong></span><span><small>检查结果</small><strong>{skill.evaluation.status==='passed'?'已通过':skill.evaluation.status}</strong></span><span><small>输出格式</small><strong>{skill.output_schemas.length}</strong></span></section><div className="operations-grid operations-capability-grid"><section className="operations-section"><SectionTitle kicker="来源与核验" title="来源、记录和安全验证" action={<span className="operations-muted">仅供查看</span>}/><dl className="operations-release-details"><div><dt>系统名称</dt><dd><code>{skill.id}</code></dd></div><div><dt>内容记录</dt><dd><code>{skill.digest}</code></dd></div><div><dt>来源地址</dt><dd><code>{skill.source.repository}</code></dd></div><div><dt>指定版本来源</dt><dd><code>{skill.source.ref}</code></dd></div><div><dt>许可证</dt><dd>{skill.source.license}</dd></div><div><dt>安全验证信息</dt><dd><code>{skill.signature.algorithm} / {skill.signature.key_id}</code></dd></div><div><dt>适用配置</dt><dd>{skill.compatible_profiles.join('、')||'未登记'}</dd></div></dl></section><section className="operations-section"><SectionTitle kicker="使用范围" title="权限、数据流和成本"/><dl className="operations-release-details"><div><dt>使用权限</dt><dd>{skill.permissions.join('、')||'未登记'}</dd></div><div><dt>默认处理位置</dt><dd>{skill.data_flow.local_by_default?'默认在工作电脑处理':'未说明默认处理位置'}</dd></div><div><dt>平台操作</dt><dd>{skill.data_flow.cloud_actions.join('、')||'未说明平台操作'}</dd></div><div><dt>费用方式</dt><dd>{skillCostLabel(skill.cost.model,skill.cost.currency,skill.cost.unit,skill.cost.unit_price)}</dd></div><div><dt>费用说明</dt><dd>{skill.cost.notice}</dd></div><div><dt>当前状态</dt><dd>{skill.revocation.status==='active'?'当前有效':skill.revocation.reason||'已停用'}</dd></div></dl></section></div><div className="operations-grid operations-capability-grid"><section className="operations-section"><SectionTitle kicker="输出格式" title={`${skill.output_schemas.length} 个已登记输出格式`}/><div className="operations-list">{skill.output_schemas.map(schema=><div className="operations-list-row" key={schema}><span className="operations-object-icon info"><FileCheck2 size={16}/></span><span><strong>{schema}</strong><small>系统登记的输出格式</small></span><span/><span/></div>)}</div></section><section className="operations-section"><SectionTitle kicker="检查记录" title={`${skill.evaluation.evidence.length} 项记录`}/><dl className="operations-release-details"><div><dt>检查状态</dt><dd><Status value={skill.evaluation.status}/></dd></div><div><dt>检查报告</dt><dd><code>{skill.evaluation.report||'未登记'}</code></dd></div><div><dt>检查记录</dt><dd><code>{skill.evaluation.digest||'未登记'}</code></dd></div><div><dt>记录内容</dt><dd>{skill.evaluation.evidence.join('、')||'未登记'}</dd></div></dl></section></div><section className="operations-section operations-capability-environments"><SectionTitle kicker="信息完整度" title="功能说明还不完整" action={<Link to={adminPath('capabilities')}>查看功能清单 <ArrowRight size={14}/></Link>}/><p className="operations-release-note is-warning"><AlertTriangle size={16}/><span>当前登记信息还缺少功能关联、输入输出说明、负责人、使用手册、可用工具和影响范围等内容。本页不会据此判断这项功能已经批准或已被客户使用。</span></p></section></div>;
}

export function AdminExecutorsPage() {
  const {executorDirectory,executorDirectoryError,refresh}=useAdmin();
  if(executorDirectoryError)return <OperationsEmpty title="连接的电脑暂不可用" detail={executorDirectoryError} action={<Button variant="secondary" onClick={()=>refresh(true)}><RefreshCw size={15}/>重新加载</Button>}/>;
  if(!executorDirectory)return <OperationsEmpty title="连接的电脑暂不可用" detail="暂时无法读取连接的电脑，请稍后刷新。"/>;
  return <div className="operations-page"><PageIntro eyebrow="功能设置 / 连接的电脑" title="连接的电脑" description="查看电脑连接、功能准备情况和正在处理的任务。" action={<button className="icon-button operations-refresh" aria-label="刷新电脑状态" title="刷新电脑状态" onClick={()=>refresh(true)}><RefreshCw size={16}/></button>}/><section className="operations-section"><SectionTitle kicker="已连接电脑" title={`${executorDirectory.executors.length} 台电脑`} action={<span className="operations-muted">状态更新窗口：{executorDirectory.online_window_seconds} 秒</span>}/><div className="operations-table operations-executor-table"><header><span>电脑</span><span>连接状态</span><span>功能准备</span><span>任务处理</span><span>正在处理</span><span/></header>{executorDirectory.executors.length===0?<Empty title="还没有连接电脑" detail="客户完成连接后，电脑信息会显示在这里。"/>:executorDirectory.executors.map(item=><Link className="operations-table-row" to={adminExecutorPath(item.id)} key={item.id}><span className="operations-primary-cell"><span className={`operations-object-icon ${executorStatusTone(item.presence_status)}`}><Activity size={16}/></span><span><strong>{item.display_name||item.hostname}</strong><small>{item.version||'版本未登记'} · 最近更新 {dateTime(item.last_seen_at)}</small></span></span><span><Status value={item.presence_status}/></span><span><Status value={item.environment_status}/></span><span><Status value={item.runtime_status}/></span><span>{item.active_attempt_ids.length} 个</span><ArrowRight size={15}/></Link>)}</div></section></div>;
}

export function AdminExecutorDetailPage() {
  const {executorID=''}=useParams();
  const {executorDirectory,executorDirectoryError,session,refresh}=useAdmin();
  const [busy,setBusy]=useState('');
  const [notice,setNotice]=useState('');
  const [newDeviceToken,setNewDeviceToken]=useState('');
  if(executorDirectoryError)return <OperationsEmpty title="电脑详情暂不可用" detail={executorDirectoryError} action={<Button variant="secondary" onClick={()=>refresh(true)}><RefreshCw size={15}/>重新加载</Button>}/>;
  if(!executorDirectory)return <OperationsEmpty title="连接的电脑暂不可用" detail="暂时无法读取电脑详情，请稍后刷新。"/>;
  const executor=executorDirectory.executors.find(item=>item.id===executorID);
  if(!executor)return <OperationsNotFound eyebrow="功能设置 / 连接的电脑" title="没有找到这台电脑" detail="它可能还没有连接，或者当前账号无权查看。" href={adminPath('executors')} returnLabel="返回连接的电脑"/>;
  const canManage=['tenant_admin','project_manager'].includes(session.role)&&!executor.revoked_at;
  const runtimes=executor.runtimes||[];
  const workspaces=executor.workspaces||[];
  const reload=async()=>{setBusy('refresh');setNotice('');try{await refresh(true);setNotice('电脑状态已刷新。');}catch(value){setNotice(value instanceof Error?value.message:'电脑状态刷新失败');}finally{setBusy('');}};
  const rotateCredential=async()=>{if(!window.confirm('确认更换这台电脑的连接密钥？旧密钥会立即失效，需要把新密钥更新到对应电脑。'))return;setBusy('rotate');setNotice('');setNewDeviceToken('');try{const result=await post<{device_token:string}>(`/api/bff/devices/${encodeURIComponent(executor.id)}/credentials/rotate`);setNewDeviceToken(result.device_token);setNotice('连接密钥已更换。新密钥仅在此处显示，请立即更新到对应电脑。');await refresh(true);}catch(value){setNotice(value instanceof Error?value.message:'连接密钥更换失败');}finally{setBusy('');}};
  const revoke=async()=>{if(!window.confirm('确认断开这台电脑？它将不能继续领取任务或上报状态，现有连接密钥也会失效。'))return;setBusy('revoke');setNotice('');try{await post(`/api/bff/devices/${encodeURIComponent(executor.id)}/revoke`);setNotice('电脑连接已断开。');await refresh(true);}catch(value){setNotice(value instanceof Error?value.message:'电脑连接断开失败');}finally{setBusy('');}};
  const copyToken=async()=>{try{await navigator.clipboard.writeText(newDeviceToken);setNotice('新连接密钥已复制。');}catch{setNotice('无法自动复制，请从当前页面手动复制新连接密钥。');}};
  return <div className="operations-page operations-executor-page">
    <Link className="operations-back-link" to={adminPath('executors')}><ArrowLeft size={15}/>返回连接的电脑</Link>
    <PageIntro eyebrow="功能设置 / 连接的电脑" title={executor.display_name||executor.hostname} description="检查电脑连接、功能准备情况和当前正在处理的任务。" action={<><Link className="button button-secondary" to={adminPath('jobs')}><Wrench size={15}/>查看任务详情</Link><Button variant="secondary" disabled={Boolean(busy)} onClick={()=>void reload()}><RefreshCw className={busy==='refresh'?'is-spinning':''} size={15}/>刷新状态</Button>{canManage&&<Button variant="secondary" disabled={Boolean(busy)} onClick={()=>void rotateCredential()}><KeyRound size={15}/>更换连接密钥</Button>}{canManage&&<Button variant="danger" disabled={Boolean(busy)} onClick={()=>void revoke()}><Ban size={15}/>断开电脑</Button>}</>}/>
    {notice&&<p className={`operations-executor-notice ${newDeviceToken?'is-warning':''}`} role="status">{notice}</p>}
    {newDeviceToken&&<div className="operations-device-token"><div><small>一次性新连接密钥</small><code>{newDeviceToken}</code></div><button className="icon-button" aria-label="复制新连接密钥" title="复制新连接密钥" onClick={()=>void copyToken()}><Copy size={16}/></button></div>}
    <section className="operations-executor-health" aria-label="电脑状态"><ExecutorHealthAxis label="电脑连接" status={executor.presence_status} reason={executor.presence_reason}/><ExecutorHealthAxis label="功能准备" status={executor.environment_status} reason={executor.environment_reason}/><ExecutorHealthAxis label="任务处理" status={executor.runtime_status} reason={executor.runtime_reason}/></section>
    <section className="operations-release-facts" aria-label="电脑摘要"><span><small>软件版本</small><strong>{executor.version||'未登记'}</strong></span><span><small>电脑系统</small><strong>{[executor.platform,executor.arch].filter(Boolean).join(' / ')||'未登记'}</strong></span><span><small>正在处理</small><strong>{executor.active_attempt_ids.length}</strong></span><span><small>可访问项目</small><strong>{executor.projects.length}</strong></span></section>
    <div className="operations-grid operations-capability-grid">
      <section className="operations-section"><SectionTitle kicker="电脑信息" title="连接信息" action={<span className="operations-muted">最新状态</span>}/><dl className="operations-release-details"><div><dt>电脑标识</dt><dd><code>{executor.id}</code></dd></div><div><dt>连接记录</dt><dd><code>{executor.daemon_instance_id||'尚未上报'}</code></dd></div><div><dt>连接状态记录</dt><dd>{executor.connection_epoch||'尚未上报'}</dd></div><div><dt>最近更新</dt><dd>{dateTime(executor.last_seen_at)}</dd></div><div><dt>电脑名称</dt><dd><code>{executor.hostname||'未登记'}</code></dd></div><div><dt>所属客户</dt><dd>{session.tenant.name}</dd></div>{executor.revoked_at&&<div><dt>断开时间</dt><dd>{dateTime(executor.revoked_at)}</dd></div>}</dl></section>
      <section className="operations-section"><SectionTitle kicker="正在处理" title={`${executor.active_attempt_ids.length} 个任务正在处理`} action={<Link to={adminPath('jobs')}>查看任务进度 <ArrowRight size={14}/></Link>}/><div className="operations-list">{executor.active_attempt_ids.length===0?<Empty title="没有正在处理的任务" detail="这台电脑当前没有上报正在处理的任务。"/>:executor.active_attempt_ids.map(attemptID=><div className="operations-list-row" key={attemptID}><span className="operations-object-icon production"><Activity size={16}/></span><span><strong>{attemptID}</strong><small>由这台电脑上的连接工具上报</small></span><span className="operations-row-status">处理中</span><span/></div>)}</div></section>
    </div>
    <section className="operations-section operations-runtime-inventory"><SectionTitle kicker="电脑上的工具" title={`${runtimes.length} 个工具已发现`} action={<span className="operations-muted">启动后每 5 分钟更新</span>}/><div className="operations-list">{runtimes.length===0?<Empty title="还没有工具状态" detail="电脑上的连接工具版本较旧，或状态还没有同步。"/>:runtimes.map(runtime=><div className="operations-list-row" key={runtime.kind}><span className={`operations-object-icon ${runtime.status==='healthy'?'success':'warning'}`}><Wrench size={16}/></span><span><strong>电脑工具 {runtime.kind}{runtime.selected?' · 当前使用':''}</strong><small>{runtime.version||runtime.error_code||'版本未登记'}</small></span><Status value={runtime.status}/><span/></div>)}</div></section>
    <section className="operations-section operations-workspace-inventory"><SectionTitle kicker="项目文件夹" title={`${workspaces.length} 个项目文件夹已检查`} action={<span className="operations-muted">启动后每 30 秒更新</span>}/><div className="operations-workspace-list">{workspaces.length===0?<Empty title="还没有项目文件夹状态" detail="电脑还没有连接项目文件夹，或状态还没有同步。"/>:workspaces.map(workspace=>{const project=executor.projects.find(item=>item.id===workspace.project_id);return <article className="operations-workspace-row" key={workspace.workspace_id}><header><span className={`operations-object-icon ${executorStatusTone(workspace.status)}`}><FolderKanban size={16}/></span><div><strong>{project?executorProjectName(project.brand_name,project.product_name):workspace.project_id}</strong><small>{executorHealthReason(workspace.reason)}</small></div><Status value={workspace.status}/></header><dl><div><dt>文件夹标识</dt><dd><code>{workspace.workspace_id}</code></dd></div><div><dt>项目标识</dt><dd><code>{workspace.project_id}</code></dd></div><div><dt>最近状态记录</dt><dd><code>{workspace.generation||'尚未上报'}</code></dd></div><div><dt>最近检查</dt><dd>{dateTime(workspace.observed_at)}</dd></div></dl></article>})}</div></section>
    <div className="operations-grid operations-capability-grid"><section className="operations-section"><SectionTitle kicker="项目范围" title={`${executor.projects.length} 个项目已授权`}/><div className="operations-list">{executor.projects.length===0?<Empty title="没有可访问的项目" detail="这台电脑当前没有可访问的项目。"/>:executor.projects.map(project=><div className="operations-list-row" key={project.id}><span className="operations-object-icon strategy"><FolderKanban size={16}/></span><span><strong>{executorProjectName(project.brand_name,project.product_name)}</strong><small>{project.id}</small></span><Status value={project.status}/><span/></div>)}</div></section><section className="operations-section"><SectionTitle kicker="可用功能" title={`${executor.capabilities.length} 个功能版本`} action={<Link to={adminPath('capabilities')}>查看功能清单 <ArrowRight size={14}/></Link>}/><div className="operations-list">{executor.capabilities.length===0?<Empty title="没有可用功能记录" detail="电脑下次更新状态后会显示可用功能。"/>:executor.capabilities.map(capability=><Link className="operations-list-row" to={adminCapabilityPath(capability.id,capability.version)} key={`${capability.id}:${capability.version}`}><span className="operations-object-icon info"><Sparkles size={16}/></span><span><strong>{capabilityLabel(capability.id)}</strong><small>v{capability.version} · {capability.local_only?'由工作电脑处理':'可由平台或外部服务处理'}</small></span><span className="operations-row-status">查看详情</span><ArrowRight size={14}/></Link>)}</div></section></div>
    <p className="operations-release-note"><CircleDashed size={15}/><span>这里显示电脑最近一次上报的状态。电脑软件、可用功能或项目文件夹发生变化后，系统会重新建立连接；已经开始的任务不会被改写。</span></p>
  </div>;
}

function AdminCustomerDirectory({mode}:{mode:'enrollments'|'management'}) {
  const {workOS,refresh}=useAdmin();
  const navigate=useNavigate();
  const [searchParams]=useSearchParams();
  const enrollment=mode==='enrollments';
  const title=enrollment?'客户设置':'客户列表';
  if(!workOS)return <OperationsEmpty title={`${title}暂不可用`} detail="暂时无法读取客户设置，请稍后刷新。"/>;
  const productID=enrollment?searchParams.get('product')||'':'';
  const filteredProduct=workOS.sops.find(item=>item.definition.id===productID);
  if(enrollment)return <div className="operations-page operations-customer-page"><PageIntro eyebrow="内容管理 / 客户设置" title="客户设置" description={filteredProduct?`正在查看使用「${filteredProduct.definition.name}」的客户。选择客户可调整默认流程和可用功能。`:'为客户选择默认的创作流程，并调整后续新创作可以使用的功能。'} action={filteredProduct?<Link className="button button-secondary" to={adminPath('customers')}>清除流程筛选</Link>:<Link className="button button-secondary" to={adminPath('products')}>查看创作流程</Link>}/><AdminEnvironmentPanel environments={workOS.environments} sops={workOS.sops} availableCapabilities={workOS.capabilities} variant="enrollment" directoryOnly filterProductID={filteredProduct?.definition.id} initialProductID={filteredProduct?.definition.id} onSaved={()=>refresh(true)} environmentPath={adminCustomerPath} onSelectionChange={environmentID=>navigate(adminCustomerPath(environmentID))} onCreated={environmentID=>navigate(adminCustomerPath(environmentID))}/></div>;
  return <div className="operations-page"><PageIntro eyebrow={`${enrollment?'内容管理':'账号与记录'} / ${title}`} title={title} description={enrollment?'查看每个客户正在使用的创作流程和功能范围。':'查看客户状态、连接的电脑和创作流程设置。'}/><section className="operations-section"><SectionTitle kicker={enrollment?'使用设置':'客户目录'} title={`${workOS.environments.length} 个客户`} action={<span className="operations-muted">一个客户可能有多台连接的电脑</span>}/><div className="operations-table"><header><span>客户</span><span>状态</span><span>创作流程</span><span>可用功能</span><span>最近更新</span><span/></header>{workOS.environments.length===0?<Empty title={`还没有${title}记录`} detail="保存客户设置后会显示在这里。"/>:workOS.environments.map(item=><div className="operations-table-row" key={item.id}><span className="operations-primary-cell"><span className="operations-object-icon success"><Users size={16}/></span><span><strong>{item.name}</strong><small>已建立客户设置</small></span></span><span><Status value={item.status}/></span><span>{productName(workOS,item.default_sop_id,item.default_sop_version)}</span><span>{item.capabilities.filter(capability=>capability.enabled).length} 项</span><span>{dateTime(item.updated_at)}</span><Link className="icon-button" aria-label={`查看${item.name}的客户设置`} title="查看客户设置" to={adminCustomerPath(item.id)}><ArrowRight size={15}/></Link></div>)}</div></section></div>;
}

export function AdminCustomerDetailPage() {
  const {environmentID=''}=useParams();
  const {workOS,refresh}=useAdmin();
  if(!workOS)return <OperationsEmpty title="客户设置暂不可用" detail="暂时无法读取客户设置详情，请稍后刷新。"/>;
  const environment=workOS.environments.find(item=>item.id===environmentID);
  if(!environment)return <OperationsNotFound eyebrow="内容管理 / 客户设置" title="没有找到这条客户设置" detail="它可能尚未创建，或者当前账号无权查看。" href={adminPath('customers')} returnLabel="返回客户设置"/>;
  const product=workOS.sops.find(item=>item.definition.id===environment.default_sop_id);
  return <div className="operations-page operations-customer-page"><Link className="operations-back-link" to={adminPath('customers')}><ArrowLeft size={15}/>返回客户设置</Link><PageIntro eyebrow="内容管理 / 客户设置" title={environment.name} description="维护这个客户使用的创作流程、启用状态和可用功能。" action={product?<Link className="button button-secondary" to={adminProductVersionPath(product.definition.id,environment.default_sop_version||product.definition.current_version)}><FolderKanban size={15}/>查看创作流程</Link>:undefined}/><AdminEnvironmentPanel environments={workOS.environments} sops={workOS.sops} availableCapabilities={workOS.capabilities} variant="enrollment" scoped initialEnvironmentID={environment.id} onSaved={()=>refresh(true)}/></div>;
}

export function AdminAlertsPage() {
  const {workOS}=useAdmin();
  if(!workOS)return <OperationsEmpty title="需要处理暂不可用" detail="暂时无法读取等待和异常事项，请稍后刷新。"/>;
  const blocking=workOS.gates.filter(item=>item.blocking);
  return <div className="operations-page"><PageIntro eyebrow="任务跟进 / 需要处理" title="需要处理" description="先处理会让客户任务停下来的等待事项。"/><section className="operations-section"><SectionTitle kicker="当前待办" title={`${workOS.usage.waiting_gate_count} 个任务等你确认`} action={<Link to={adminPath('jobs')}>查看任务进度 <ArrowRight size={14}/></Link>}/><div className="operations-list">{blocking.length===0?<Empty title="目前没有卡住的任务" detail="任务异常和等待确认会显示在这里。"/>:blocking.map(item=><div className="operations-list-row" key={`${item.sop_id}:${item.sop_version}:${item.gate_id}`}><span className="operations-object-icon warning"><AlertTriangle size={16}/></span><span><strong>{item.name}</strong><small>{item.sop_name} v{item.sop_version} · {item.usage_count} 个任务正在使用</small></span><span className="operations-row-status">需要确认</span><ArrowRight size={14}/></div>)}</div></section></div>;
}

export function AdminAuditPage() {
  const {workOS}=useAdmin();
  if(!workOS)return <OperationsEmpty title="操作审计暂不可用" detail="暂时无法读取操作记录，请稍后刷新。"/>;
  return <div className="operations-page"><PageIntro eyebrow="账号与记录 / 变更记录" title="变更记录" description="查看内容流程、客户设置和任务状态的变化。"/><section className="operations-section"><SectionTitle kicker="最近记录" title={`${workOS.audit.length} 条变更记录`} action={<span className="operations-muted">按时间倒序</span>}/><div className="operations-table"><header><span>发生了什么</span><span>涉及内容</span><span>编号</span><span>结果</span><span>发生时间</span><span/></header>{workOS.audit.length===0?<Empty title="还没有变更记录" detail="发布、配置和任务变更会记录在这里。"/>:workOS.audit.map(item=><div className="operations-table-row" key={item.id}><span className="operations-primary-cell"><span className="operations-object-icon success"><ShieldCheck size={16}/></span><span><strong>{auditActionLabel(item.action)}</strong><small>{item.id}</small></span></span><span>{auditSubjectLabel(item.subject_type)}</span><span>{item.subject_id}</span><span>已记录</span><span>{dateTime(item.created_at)}</span><span/></div>)}</div></section></div>;
}

export function AdminCostsPage() {
  const {workOS}=useAdmin();
  if(!workOS)return <OperationsEmpty title="任务用量暂不可用" detail="暂时无法读取任务用量，请稍后刷新。"/>;
  const modes=Object.entries(workOS.usage.by_execution_mode);
  return <div className="operations-page"><PageIntro eyebrow="平台管理 / 任务用量" title="任务用量" description="按任务状态和处理方式核对平台返回的实际用量。"/><section className="operations-section"><SectionTitle kicker="任务统计" title={`${workOS.usage.task_count} 个任务`}/><div className="operations-health-list"><HealthLine label="正在运行" value={workOS.usage.running_count} tone="info"/><HealthLine label="等待确认" value={workOS.usage.waiting_gate_count} tone="warning"/>{modes.map(([mode,value])=><HealthLine key={mode} label={executionModeName(mode)} value={value} tone="success"/>)}</div></section></div>;
}

function PageIntro({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:ReactNode}) { return <header className="operations-page-intro"><div><span className="operations-eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action&&<div className="operations-page-actions">{action}</div>}</header>; }
function SectionTitle({kicker,title,action}:{kicker:string;title:string;action?:ReactNode}) { return <header className="operations-section-title"><div><span>{kicker}</span><h2>{title}</h2></div>{action}</header>; }
function SummaryStat({icon:Icon,label,value,detail,tone,onClick}:{icon:typeof Activity;label:string;value:string;detail:string;tone:string;onClick:()=>void}) { return <button className={`operations-stat ${tone}`} onClick={onClick}><span className="operations-stat-icon"><Icon size={17}/></span><span><strong>{value}</strong><b>{label}</b><small>{detail}</small></span><ArrowRight size={14}/></button>; }
function OperationRow({icon:Icon,tone,title,detail,action,href}:{icon:typeof Activity;tone:string;title:string;detail:string;action:string;href:string}) { return <Link className="operations-list-row" to={href}><span className={`operations-object-icon ${tone}`}><Icon size={16}/></span><span><strong>{title}</strong><small>{detail}</small></span><span className="operations-row-action">{action}</span><ArrowRight size={14}/></Link>; }
function HealthLine({label,value,tone}:{label:string;value:number|string;tone:string}) { return <div className="operations-health-line"><span className={`operations-health-dot ${tone}`}/><span>{label}</span><strong>{value}</strong></div>; }
function OperationsEmpty({title,detail,action}:{title:string;detail:string;action?:ReactNode}) { return <div className="operations-page"><PageIntro eyebrow="平台运营后台" title={title} description={detail}/><section className="operations-section"><Empty title={title} detail={detail} action={action}/></section></div>; }
function OperationsNotFound({title,detail,href=adminPath('products'),eyebrow='创作运营 / 创作产品',returnLabel='返回产品列表'}:{title:string;detail:string;href?:string;eyebrow?:string;returnLabel?:string}) { return <div className="operations-page"><PageIntro eyebrow={eyebrow} title={title} description={detail}/><section className="operations-section"><Empty title={title} detail={detail} action={<Link className="button button-secondary" to={href}><ArrowLeft size={15}/>{returnLabel}</Link>}/></section></div>; }
function auditLabel(value:string) { const labels:Record<string,string>={sop_version_published:'发布流程版本',sop_version_updated:'更新流程版本',environment_updated:'更新客户设置',task_created:'创建任务',task_stage_reported:'更新任务进度',knowledge_decision:'完成内容审核'}; return labels[value]||value.replace(/_/g,' '); }
function capabilityLabel(value:string) { const labels:Record<string,string>={inspiration_collection:'灵感采集',persona_generation:'人物原型',script_generation:'剧本创作',storyboard_generation:'分镜设计',video_generation:'视频制作'}; return labels[value]||value.replace(/_/g,' '); }
function capabilityDescription(value:string) { const labels:Record<string,string>={inspiration_collection:'收集并整理与创作主题有关的资料',persona_generation:'形成可复用的人物设定',script_generation:'生成结构化剧本内容',storyboard_generation:'把剧本转换为镜头画面方案',video_generation:'根据分镜制作视频结果'}; return labels[value]||'已登记的创作能力'; }
function capabilityKindName(value:string) { const labels:Record<string,string>={search:'资料采集',generation:'内容生成',review:'内容检查',delivery:'结果交付'}; return labels[value]||'标准能力'; }
function executorTypeName(value:string) { return value==='contentcloud_device'?'连接的电脑':'未知连接类型'; }
function executorStatusTone(value:string) { return ['online','ready','healthy'].includes(value)?'success':['offline','repair_required','degraded','throttled','unavailable'].includes(value)?'warning':value==='blocked'?'warning':'info'; }
function executorHealthReason(value?:string) { const labels:Record<string,string>={instance_connected:'连接正常',instance_degraded:'已连接，但部分功能不可用',instance_stopped:'连接服务已停止',instance_stale:'状态较久未更新',instance_not_reported:'还没有收到电脑状态',registration_revoked:'电脑连接已断开',not_reported:'还没有收到电脑状态',plugin_drift:'电脑上的功能与登记不一致',skill_drift:'自动化功能版本与登记不一致',mcp_drift:'外部工具连接与登记不一致',managed_files_drift:'受管理文件与登记不一致',workspace_binding_mismatch:'项目文件夹与电脑连接不一致',workspace_observation_failed:'项目文件夹检查失败',workspace_root_unavailable:'项目文件夹位置不可用',local_components_observed:'电脑上的组件已检查',all_workspaces_ready:'所有项目文件夹都已准备好',capacity_limit:'当前处理能力已满',development_fixture:'开发环境演示状态'}; return value?labels[value]||value:'暂未提供原因'; }
function ExecutorHealthAxis({label,status,reason}:{label:string;status:string;reason?:string}) { return <div className={`operations-executor-axis is-${executorStatusTone(status)}`}><span>{label}</span><Status value={status}/><small>{executorHealthReason(reason)}</small></div>; }
function executorProjectName(brandName:string,productName:string) { return [brandName,productName].filter(Boolean).join(' / ')||'项目名称未登记'; }
function capabilityProductCount(workOS:NonNullable<ReturnType<typeof useAdmin>['workOS']>,capabilityID:string) { return workOS.sops.filter(summary=>summary.versions.some(version=>version.stages.some(stage=>stage.required_capabilities.includes(capabilityID)))).length; }
function productName(workOS:NonNullable<ReturnType<typeof useAdmin>['workOS']>,sopID?:string,version?:number) { const name=workOS.sops.find(item=>item.definition.id===sopID)?.definition.name; return name?`${name}${version?` v${version}`:''}`:'尚未开通'; }
function executionModeName(value:string) { const labels:Record<string,string>={managed:'平台处理',local:'工作电脑处理',manual:'人工处理',provider:'外部服务处理'}; return labels[value]||'其他处理方式'; }
function skillCostLabel(model:string,currency?:string,unit?:string,unitPrice?:string) { const labels:Record<string,string>={free:'免费',included:'已包含',metered:'按量计费',external:'外部结算'}; const price=model==='metered'&&currency&&unit&&unitPrice?` · ${currency} ${unitPrice}/${unit}`:''; return `${labels[model]||model}${price}`; }
